// ArgocdConfig locates the ArgoCD instance that reconciles this repository.
type ArgocdConfig struct {
	Server string `yaml:"server"`

	// AppNamespace is the namespace the Application objects live in. It is not
	// optional in practice: the ApplicationSets are deployed per customer
	// (e.g. customer-wsf) rather than into argocd, and omitting appNamespace
	// from an API call against such an installation returns a 404 that is
	// indistinguishable from "no such application".
	AppNamespace string `yaml:"appNamespace"`
}

// EnvironmentConfig is one entry under environments.
type EnvironmentConfig struct {
	// Sync is "auto" or "manual".
	Sync string `yaml:"sync"`

	// PromotesFrom lists environments a promotion into this one may draw
	// from. Deploy reads it to report whether the digests being deployed are
	// what those environments already run; enforcing it is the promote
	// command's job.
	PromotesFrom []string `yaml:"promotesFrom"`

	// RequireSourceHealthy demands the source environment be healthy before a
	// promotion into this one. Parsed here, enforced by promote.
	RequireSourceHealthy bool `yaml:"requireSourceHealthy"`

	// Scratch marks an environment as disposable. The semantics are not yet
	// defined, so this is carried but never acted on — parsing it now means a
	// repository that already sets it is not rejected as malformed.
	Scratch bool `yaml:"scratch"`
}

// ComponentConfig is the parsed component.yaml.
type ComponentConfig struct {
	SchemaVersion int    `yaml:"schemaVersion"`
	Name          string `yaml:"name"`

	// Kind is KindService or KindShared; empty means KindService, so every
	// component.yaml written before this field existed keeps working.
	Kind string `yaml:"kind"`

	// SourcePaths are the paths in the *source* repository that make up this
	// component. The working-tree cleanliness check is scoped to them, so an
	// unrelated dirty file elsewhere in a monorepo does not block a deploy.
	SourcePaths []string `yaml:"sourcePaths"`

	// Images are the image repositories to pin. Explicit rather than derived:
	// existing repositories name images inconsistently, and a wrong guess
	// silently adds an inert images[] entry instead of failing.
	Images []ImageRef `yaml:"images"`

	// Environments are the environments this component may deploy to.
	Environments []string `yaml:"environments"`
}

// ImageRef names one image repository, without a tag or digest.
type ImageRef struct {
	Name string `yaml:"name"`
}

// LoadDeployConfig reads and validates deploy.yaml from the root of a GitOps
// repository.
func LoadDeployConfig(root string) (*DeployConfig, error) {
	path := filepath.Join(root, DeployFileName)
	var cfg DeployConfig
	if err := decodeFile(path, &cfg); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("%s has no %s, so it is not a GitOps repository this CLI can deploy through", root, DeployFileName)
		}
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *DeployConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Registry == "" {
		return fmt.Errorf("%s: registry is required", path)
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	for _, name := range slices.Sorted(maps.Keys(c.Environments)) {
		env := c.Environments[name]
		switch env.Sync {
		case SyncAuto, SyncManual:
		case "":
			return fmt.Errorf("%s: environment %q has no sync policy (expected %q or %q)", path, name, SyncAuto, SyncManual)
		default:
			return fmt.Errorf("%s: environment %q has sync %q (expected %q or %q)", path, name, env.Sync, SyncAuto, SyncManual)
		}
		for _, src := range env.PromotesFrom {
			if _, ok := c.Environments[src]; !ok {
				return fmt.Errorf("%s: environment %q promotes from %q, which is not defined", path, name, src)
			}
		}
	}
	return nil
}

// Environment returns the named environment's policy, or an error listing the
// environments the repository does define.
func (c *DeployConfig) Environment(name string) (EnvironmentConfig, error) {
	env, ok := c.Environments[name]
	if !ok {
		return EnvironmentConfig{}, fmt.Errorf("unknown environment %q; %s defines: %s", name, DeployFileName, strings.Join(c.EnvironmentNames(), ", "))
	}
	return env, nil
}

// EnvironmentNames returns the defined environment names in sorted order.
func (c *DeployConfig) EnvironmentNames() []string {
	return slices.Sorted(maps.Keys(c.Environments))
}

// PromotionOrder returns the environments in the order changes flow through
// them: an environment comes after every environment it promotes from. Ties
// break alphabetically, so the order is stable across runs.
//
// EnvironmentNames sorts alphabetically, which renders the usual three as dev,
// prod, staging. That is the wrong story for anything presenting environments
// as a pipeline — the promotion graph is what says prod comes last.
func (c *DeployConfig) PromotionOrder() []string {
	// Sources counts the not-yet-emitted environments each one promotes from.
	// An edge naming an undefined environment is impossible here: validate
	// rejects the file first.
	remaining := make(map[string]int, len(c.Environments))
	for name, env := range c.Environments {
		sources := 0
		for _, src := range env.PromotesFrom {
			// A self-edge is not a dependency on anything else, and counting it
			// would make the environment permanently unemittable.
			if src != name {
				sources++
			}
		}
		remaining[name] = sources
	}

	order := make([]string, 0, len(c.Environments))
	for len(remaining) > 0 {
		ready := make([]string, 0, len(remaining))
		for name, sources := range remaining {
			if sources == 0 {
				ready = append(ready, name)
			}
		}

		// Nothing is ready, so the remainder is a cycle. deploy.yaml's
		// validation does not forbid one, and dropping those environments would
		// hide them from a caller listing what exists — emit them alphabetically
		// instead.
		if len(ready) == 0 {
			order = append(order, slices.Sorted(maps.Keys(remaining))...)
			break
		}

		slices.Sort(ready)
		order = append(order, ready...)
		for _, name := range ready {
			delete(remaining, name)
		}
		// Emitting a whole rank at a time keeps siblings adjacent and
		// alphabetical, rather than interleaving them by discovery order.
		for _, name := range ready {
			for other, env := range c.Environments {
				if _, pending := remaining[other]; !pending {
					continue
				}
				for _, src := range env.PromotesFrom {
					if src == name {
						remaining[other]--
					}
				}
			}
		}
	}
	return order
}

// LoadComponentConfig reads and validates a component.yaml from a component
// directory.
func LoadComponentConfig(dir string) (*ComponentConfig, error) {
	path := filepath.Join(dir, ComponentFileName)
	var cfg ComponentConfig
	if err := decodeFile(path, &cfg); err != nil {
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *ComponentConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Name == "" {
		return fmt.Errorf("%s: name is required", path)
	}
	switch c.Kind {
	case "", KindService, KindShared:
	default:
		return fmt.Errorf("%s: kind %q is not valid (expected %q or %q)", path, c.Kind, KindService, KindShared)
	}
	if c.IsShared() {
		// An images entry that matches nothing is inert rather than fatal, so a
		// shared component listing one would look pinnable and never be pinned.
		if len(c.Images) > 0 {
			return fmt.Errorf("%s: kind %q must not declare images — there is no workload to pin", path, KindShared)
		}
	} else if len(c.Images) == 0 {
		return fmt.Errorf("%s: at least one entry under images is required — there is nothing to pin otherwise", path)
	}
	for i, img := range c.Images {
		if img.Name == "" {
			return fmt.Errorf("%s: images[%d] has no name", path, i)
		}
		if hasTagOrDigest(img.Name) {
			return fmt.Errorf("%s: images[%d] name %q must be a bare repository, without a tag or digest", path, i, img.Name)
		}
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	return nil
}

// SupportsEnvironment reports whether the component declares env.
func (c *ComponentConfig) SupportsEnvironment(env string) bool {
	return slices.Contains(c.Environments, env)
}

// IsShared reports whether the component holds system-level objects rather than
// a workload, and so has nothing for deploy or promote to pin.
func (c *ComponentConfig) IsShared() bool {
	return c.Kind == KindShared
}

// hasTagOrDigest reports whether an image reference carries a tag or digest.
//
// Only the final path segment is examined, because a colon earlier in the
// reference is a registry port: localhost:5555/integrations/app and
// harbor.example.com:8443/app are perfectly ordinary repositories, and
// rejecting them would rule out every registry not on the default port.
func hasTagOrDigest(image string) bool {
	last := image
	if i := strings.LastIndex(image, "/"); i >= 0 {
		last = image[i+1:]
	}
	return strings.ContainsAny(last, ":@")
}

func checkSchemaVersion(path string, got int) error {
	switch {
	case got == 0:
		return fmt.Errorf("%s: schemaVersion is required", path)
	case got > SchemaVersion:
		return fmt.Errorf("%s: schemaVersion %d is newer than this CLI supports (%d); upgrade intropy", path, got, SchemaVersion)
	case got < 1:
		return fmt.Errorf("%s: schemaVersion %d is not valid", path, got)
	}
	return nil
}

// decodeFile decodes a YAML file, rejecting unknown fields so that a
// misspelled key is a loud error rather than a setting that silently does
// nothing.
func decodeFile(path string, into any) error {
	f, err := os.Open(path)
	if err != nil {
		// Wrapped, so callers can still test for fs.ErrNotExist.
		return fmt.Errorf("read %s: %w", path, err)
	}
	defer f.Close()

	dec := yaml.NewDecoder(f)
	dec.KnownFields(true)
	if err := dec.Decode(into); err != nil {
		if errors.Is(err, io.EOF) {
			return fmt.Errorf("parse %s: file is empty", path)
		}
		return fmt.Errorf("parse %s: %w", path, err)
	}
	return nil
}

package gitops

import (
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
)

// Coordinate locates one component in a GitOps repository.
type Coordinate struct {
	Domain    string
	System    string
	Component string
}

// RelPath returns the component directory relative to the repository root,
// always slash-separated: it is used to build ArgoCD source paths, which are
// repository paths rather than filesystem paths.
func (c Coordinate) RelPath() string {
	return path.Join(DomainsDirName, c.Domain, c.System, c.Component)
}

// OverlayRelPath returns the environment's overlay directory relative to the
// repository root. This is the value ArgoCD records as spec.source.path.
func (c Coordinate) OverlayRelPath(env string) string {
	return path.Join(c.RelPath(), OverlaysDirName, env)
}

// AppName returns the ArgoCD Application name, matching the ApplicationSet
// template that generates one Application per overlay directory:
//
//	name: '{{index .path.segments 1}}-{{index .path.segments 2}}-{{index .path.segments 3}}-{{.cluster}}'
//
// where the environment is the cluster element.
func (c Coordinate) AppName(env string) string {
	return strings.Join([]string{c.Domain, c.System, c.Component, env}, "-")
}

// String renders the coordinate in the form used in messages.
func (c Coordinate) String() string {
	return c.Domain + "/" + c.System + "/" + c.Component
}

// ErrComponentNotFound reports that no component directory matched.
var ErrComponentNotFound = errors.New("component not found")

// AmbiguousComponentError reports that a component name occurs under more than
// one domain or system, so the caller must say which one it meant.
type AmbiguousComponentError struct {
	Component string
	Matches   []Coordinate
}

func (e *AmbiguousComponentError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "%q is ambiguous — it exists in %d places:", e.Component, len(e.Matches))
	for _, m := range e.Matches {
		fmt.Fprintf(&b, "\n  %s", m)
	}
	b.WriteString("\npass --domain and --system to choose one")
	return b.String()
}

// FindComponent locates a component in the repository at root.
//
// Rather than requiring the full coordinate, this globs
// domains/*/*/<component> for a directory holding a component.yaml. Deriving
// the domain and system from the caller's working directory would be cheaper
// but couples deploy to a source-repository layout that nothing enforces;
// searching the GitOps repository asks the one place that is authoritative.
//
// domain and system are optional filters. When either is set only matching
// candidates are considered, which is how an ambiguous name is resolved.
func FindComponent(root, component, domain, system string) (Coordinate, error) {
	if component == "" {
		return Coordinate{}, errors.New("no component name given")
	}

	pattern := filepath.Join(root, DomainsDirName, "*", "*", component, ComponentFileName)
	hits, err := filepath.Glob(pattern)
	if err != nil {
		return Coordinate{}, fmt.Errorf("search %s: %w", filepath.Join(root, DomainsDirName), err)
	}

	var matches []Coordinate
	for _, hit := range hits {
		componentDir := filepath.Dir(hit)
		systemDir := filepath.Dir(componentDir)
		domainDir := filepath.Dir(systemDir)
		c := Coordinate{
			Domain:    filepath.Base(domainDir),
			System:    filepath.Base(systemDir),
			Component: filepath.Base(componentDir),
		}
		if domain != "" && c.Domain != domain {
			continue
		}
		if system != "" && c.System != system {
			continue
		}
		matches = append(matches, c)
	}

	slices.SortFunc(matches, func(a, b Coordinate) int {
		return strings.Compare(a.String(), b.String())
	})

	switch len(matches) {
	case 1:
		return matches[0], nil
	case 0:
		return Coordinate{}, notFoundError(root, component, domain, system)
	default:
		return Coordinate{}, &AmbiguousComponentError{Component: component, Matches: matches}
	}
}

// notFoundError distinguishes "this component is not in the repository at all"
// from "it is there, but not where you said it was", because the fix differs.
func notFoundError(root, component, domain, system string) error {
	if domain != "" || system != "" {
		if all, err := FindComponent(root, component, "", ""); err == nil {
			return fmt.Errorf("%w: %q exists at %s, not under the domain/system given", ErrComponentNotFound, component, all)
		}
	}
	detail := fmt.Sprintf("no %s for %q under %s/", ComponentFileName, component, DomainsDirName)
	if names := listComponents(root); len(names) > 0 {
		detail += "\nthe repository defines: " + strings.Join(names, ", ")
	} else {
		detail += fmt.Sprintf("\nthe component must be onboarded first: it needs %s/<domain>/<system>/%s/{%s,base,overlays}", DomainsDirName, component, ComponentFileName)
	}
	return fmt.Errorf("%w: %s", ErrComponentNotFound, detail)
}

// ListComponents returns every component in the repository, sorted. It backs
// shell completion and the "did you mean" list, so it never fails: an
// unreadable repository yields no suggestions rather than an error.
func ListComponents(root string) []Coordinate {
	hits, err := filepath.Glob(filepath.Join(root, DomainsDirName, "*", "*", "*", ComponentFileName))
	if err != nil {
		return nil
	}
	out := make([]Coordinate, 0, len(hits))
	for _, hit := range hits {
		componentDir := filepath.Dir(hit)
		systemDir := filepath.Dir(componentDir)
		out = append(out, Coordinate{
			Domain:    filepath.Base(filepath.Dir(systemDir)),
			System:    filepath.Base(systemDir),
			Component: filepath.Base(componentDir),
		})
	}
	slices.SortFunc(out, func(a, b Coordinate) int {
		return strings.Compare(a.String(), b.String())
	})
	return out
}

func listComponents(root string) []string {
	seen := map[string]bool{}
	var names []string
	for _, c := range ListComponents(root) {
		if !seen[c.Component] {
			seen[c.Component] = true
			names = append(names, c.Component)
		}
	}
	return names
}

// ResolveOverlay validates that a component can be deployed to env and returns
// the overlay's absolute path.
//
// Both the component's declared environment list and the overlay directory are
// checked. They can disagree — a declared environment with no overlay, or an
// overlay nobody declared — and each mismatch is worth reporting distinctly
// rather than as a bare "not found".
func ResolveOverlay(root string, c Coordinate, comp *ComponentConfig, env string) (string, error) {
	dir := filepath.Join(root, filepath.FromSlash(c.OverlayRelPath(env)))

	if !comp.SupportsEnvironment(env) {
		return "", fmt.Errorf("%s does not declare environment %q in %s; it declares: %s",
			c, env, ComponentFileName, strings.Join(comp.Environments, ", "))
	}

	info, err := os.Stat(dir)
	switch {
	case err == nil && !info.IsDir():
		return "", fmt.Errorf("%s is not a directory", dir)
	case err != nil:
		available := listOverlays(root, c)
		if len(available) == 0 {
			return "", fmt.Errorf("%s has no %s/ directory, so it is not onboarded to any environment yet", c, OverlaysDirName)
		}
		return "", fmt.Errorf("%s has no overlay for %q; it has overlays for: %s",
			c, env, strings.Join(available, ", "))
	}
	return dir, nil
}

func listOverlays(root string, c Coordinate) []string {
	entries, err := os.ReadDir(filepath.Join(root, filepath.FromSlash(c.RelPath()), OverlaysDirName))
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() {
			out = append(out, e.Name())
		}
	}
	slices.Sort(out)
	return out
}

// JoinRel joins a slash-separated repository-relative path onto a filesystem
// root.
func JoinRel(root, rel string) string {
	return filepath.Join(root, filepath.FromSlash(rel))
}

package deploy

import (
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// What scaffolding does to one file.
const (
	// ActionCreate: the file is not in the repository yet.
	ActionCreate = "create"

	// ActionIdentical: already there, byte for byte. Not written, and not
	// counted as a change — this is what makes a re-run a genuine no-op.
	ActionIdentical = "identical"

	// ActionSkipExists: already there and different. Left alone, because a
	// human or a previous deploy owns it now. Reported so the difference is
	// visible rather than silently ignored.
	ActionSkipExists = "skip-exists"

	// ActionOverwrite: already there and different, and --force was given.
	ActionOverwrite = "overwrite"
)

// FileAction is one staged file's fate.
type FileAction struct {
	// Rel is relative to the repository root, slash-separated.
	Rel    string `json:"path"`
	Action string `json:"action"`
}

// Writes reports whether the action puts bytes on disk.
func (a FileAction) Writes() bool {
	return a.Action == ActionCreate || a.Action == ActionOverwrite
}

// stageRels lists every file a render produced, relative to the staging root and
// slash-separated, sorted so a plan reads in tree order.
func stageRels(stagingDir string) ([]string, error) {
	var rels []string
	err := filepath.WalkDir(stagingDir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(stagingDir, p)
		if err != nil {
			return err
		}
		rels = append(rels, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("read staged manifests: %w", err)
	}
	slices.Sort(rels)
	return rels, nil
}

// classifyStaged decides what to do with each staged file, given what is already
// in the repository.
//
// Rendering straight into the tree is never an option: the renderer overwrites,
// and an overlay holds digests intropy deploy pinned. Staging first and
// classifying second is what makes this command additive — a system gains a
// component and only that subtree is new, while everything a human has since
// edited is left exactly as it is.
func classifyStaged(stagingDir, destRoot string, rels []string, force bool) ([]FileAction, error) {
	actions := make([]FileAction, 0, len(rels))
	for _, rel := range rels {
		staged := filepath.Join(stagingDir, filepath.FromSlash(rel))
		existing := filepath.Join(destRoot, filepath.FromSlash(rel))

		current, err := os.ReadFile(existing)
		if err != nil {
			if !os.IsNotExist(err) {
				return nil, fmt.Errorf("read %s: %w", rel, err)
			}
			actions = append(actions, FileAction{Rel: rel, Action: ActionCreate})
			continue
		}
		next, err := os.ReadFile(staged)
		if err != nil {
			return nil, fmt.Errorf("read staged %s: %w", rel, err)
		}

		switch {
		case string(current) == string(next):
			actions = append(actions, FileAction{Rel: rel, Action: ActionIdentical})
		case force:
			actions = append(actions, FileAction{Rel: rel, Action: ActionOverwrite})
		default:
			actions = append(actions, FileAction{Rel: rel, Action: ActionSkipExists})
		}
	}
	return actions, nil
}

// assertForceIsSafe refuses a --force that would overwrite a pinned overlay.
//
// kustomize records a digest in the overlay's kustomization file, so replacing
// one with a freshly rendered skeleton un-deploys whatever that environment is
// running. There is no version of that a user meant to ask for, so this is a
// hard refusal rather than a warning, and it names every file so the fix is
// obvious.
func assertForceIsSafe(destRoot string, actions []FileAction) error {
	var pinned []string
	for _, a := range actions {
		if a.Action != ActionOverwrite || !isKustomizationFile(a.Rel) {
			continue
		}
		k, _, err := kustomize.ReadKustomization(filepath.Join(destRoot, filepath.FromSlash(path.Dir(a.Rel))))
		if err != nil {
			// Unreadable or absent: nothing to protect, and the render will
			// report a real problem if there is one.
			continue
		}
		for _, img := range k.Images {
			if img.Digest != "" {
				pinned = append(pinned, fmt.Sprintf("  %s pins %s at %s", a.Rel, img.Name, img.Digest))
				break
			}
		}
	}
	if len(pinned) == 0 {
		return nil
	}
	return fmt.Errorf("--force would overwrite %d overlay%s that pin a digest, un-deploying what they run:\n%s\n\nRemove those paths from the scaffold, or delete the overlay deliberately first.",
		len(pinned), plural(len(pinned)), strings.Join(pinned, "\n"))
}

func isKustomizationFile(rel string) bool {
	return slices.Contains(kustomize.KustomizationFileNames, path.Base(rel))
}

// applyStaged copies the staged files the actions say to write.
//
// Nothing is written until every action has been classified, so a failure part
// way through classification leaves the repository untouched.
func applyStaged(stagingDir, destRoot string, actions []FileAction) ([]string, error) {
	var written []string
	for _, a := range actions {
		if !a.Writes() {
			continue
		}
		src := filepath.Join(stagingDir, filepath.FromSlash(a.Rel))
		dst := filepath.Join(destRoot, filepath.FromSlash(a.Rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return written, fmt.Errorf("create %s: %w", path.Dir(a.Rel), err)
		}
		data, err := os.ReadFile(src)
		if err != nil {
			return written, fmt.Errorf("read staged %s: %w", a.Rel, err)
		}
		if err := os.WriteFile(dst, data, 0o644); err != nil {
			return written, fmt.Errorf("write %s: %w", a.Rel, err)
		}
		written = append(written, a.Rel)
	}
	return written, nil
}

// OverlaysSegment is the skeleton directory whose contents may legitimately
// differ between environments.
const OverlaysSegment = "overlays/"

// mergeRendered folds one environment's render into the unit's staged tree.
//
// A skeleton is rendered once per environment, because the renderer has no way to
// emit one overlays/<env>/ directory per value — paths are templated, not
// iterated. Everything outside overlays/ must therefore come out identical on
// every pass, and this is where that is enforced: a file that differs between two
// environments means the author used an environment-varying value somewhere it
// does not belong, and silently keeping the last pass would be a tree whose base/
// only matches one environment.
func mergeRendered(from, into, env string) error {
	return filepath.WalkDir(from, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(from, p)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		target := filepath.Join(into, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}

		next, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		if current, err := os.ReadFile(target); err == nil {
			if string(current) == string(next) {
				return nil
			}
			if !strings.HasPrefix(filepath.ToSlash(rel), OverlaysSegment) {
				return fmt.Errorf("%s renders differently for environment %q than for an earlier one; a value that varies by environment may only be used under %s",
					filepath.ToSlash(rel), env, OverlaysSegment)
			}
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		return os.WriteFile(target, next, 0o644)
	})
}

