		err = template.RenderFiltered(skeleton, pass, values, tmpl.Spec.Files)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", templateName, dirName, env, err)
